import express from 'express';
import compression from 'compression';
import cors from 'cors';
import helmet from 'helmet';
import path from 'path';
import { fileURLToPath } from 'url';
import { keysRouter } from './routes/keys.js';
import { clientProfilesRouter } from './routes/client-profiles.js';
import { conversationsRouter } from './routes/conversations.js';
import { logsRouter } from './routes/logs.js';
import { modelsRouter } from './routes/models.js';
import { proxyRouter } from './routes/proxy.js';
import { responsesRouter } from './routes/responses.js';
import { anthropicRouter } from './routes/anthropic.js';
import { fallbackRouter } from './routes/fallback.js';
import { profilesRouter } from './routes/profiles.js';
import { embeddingsRouter } from './routes/embeddings.js';
import { mediaRouter } from './routes/media.js';
import { analyticsRouter } from './routes/analytics.js';
import { healthRouter } from './routes/health.js';
import { freeTierRouter } from './routes/free-tier.js';
import { settingsRouter } from './routes/settings.js';
import { premiumRouter } from './routes/premium.js';
import { backupsRouter } from './routes/backups.js';
import { cacheRouter } from './routes/cache.js';
import { compressionRouter } from './routes/compression.js';
import { authRouter } from './routes/auth.js';
import { docsRouter } from './routes/docs.js';
import { mcpRouter } from './routes/mcp.js';
import { statusRouter, providersRouter } from './routes/status.js';
import { geminiRouter } from './routes/gemini.js';
import { ollamaRouter } from './routes/ollama.js';
import { urlTokenRouter } from './routes/url-tokens.js';
import { updateRouter } from './routes/update.js';
import { moderationRouter } from './routes/moderation.js';
import { requireAuth } from './middleware/requireAuth.js';
import { createProxyRateLimiter, createAdminRateLimiter } from './middleware/rateLimit.js';

// Password-guess ceiling for GET /api/keys/export. Deliberately low: a real
// user exports keys occasionally, never ten times a minute.
const EXPORT_RATE_LIMIT_RPM = 10;
import { errorHandler } from './middleware/errorHandler.js';
import { clientContextMiddleware } from './lib/client-context.js';
import type { Config } from './lib/config.js';
import { loadConfig } from './lib/config.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const DEFAULT_DASHBOARD_ORIGINS = [
  'http://localhost:5173',
  'http://127.0.0.1:5173',
  'http://[::1]:5173',
];

// SHA-256 of the inline theme/direction bootstrap in client/index.html, which
// must run before first paint. Kept as a literal so the CSP header stays a
// constant string; csp-inline-bootstrap.test.ts recomputes it from the real
// index.html (source and build) and fails if the two ever drift apart.
export const INLINE_BOOTSTRAP_SHA = "'sha256-4Mz/yZAENQGlTAAeE1WqXruXCripvlvl0s+Q9S1VS4A='";

// A build asset is safe to cache forever+immutable when its URL is
// content-addressed. Vite parks every hashed chunk (JS, CSS, fonts, images)
// under assets/, so that directory is the reliable signal; the -<hash>.<ext>
// suffix is a belt-and-braces fallback for any hashed file emitted elsewhere.
// index.html and other unhashed entries deliberately fall through to no-cache.
const HASHED_ASSET_RE = /-[A-Za-z0-9_-]{6,}\.[A-Za-z0-9]+$/;
function isImmutableAsset(filePath: string): boolean {
  return (
    filePath.includes(`${path.sep}assets${path.sep}`) ||
    HASHED_ASSET_RE.test(path.basename(filePath))
  );
}

// Loopback and *.localhost are "potentially trustworthy" origins even over
// plain HTTP (https://www.w3.org/TR/powerful-features/#is-origin-trustworthy),
// so a desktop/localhost install still gets the secure-context-only headers.
const LOOPBACK_HOST_RE = /^(?:localhost|[^.]+(?:\.[^.]+)*\.localhost|127(?:\.\d{1,3}){3}|\[?::1\]?)$/i;

// TLS terminated here (req.secure), or in front of us and forwarded. The
// X-Forwarded-Proto check is the documented reverse-proxy setup for publishing
// the proxy beyond localhost.
function isHttpsRequest(req: express.Request): boolean {
  const forwardedProto = req.headers['x-forwarded-proto'];
  // A proxy chain sends a comma-separated list; the client-facing hop is first.
  const first = String(forwardedProto ?? '').split(',')[0]!.trim().toLowerCase();
  return first === 'https' || req.secure;
}

// Whether the browser will treat this origin as a secure context. Headers that
// only apply to secure contexts are worse than useless elsewhere: the browser
// drops them and logs an error, which is exactly what a plain-HTTP LAN install
// reported in #734.
function isTrustworthyOrigin(req: express.Request): boolean {
  return isHttpsRequest(req) || LOOPBACK_HOST_RE.test(req.hostname ?? '');
}

export function createApp(config?: Config) {
  const cfg = config ?? loadConfig();
  const app = express();
  // TRUST_PROXY (#1024): opt-in trust of X-Forwarded-* from a reverse proxy.
  // false (default) ignores forwarded headers so direct callers cannot spoof
  // the client IP; true trusts every hop; a comma-separated list of addresses
  // /CIDRs trusts only those proxies. Must be set before client-context and
  // the rate-limit middleware, which both resolve the client IP.
  app.set('trust proxy', cfg.trustProxy);
  const allowedCorsOrigins = new Set([
    ...DEFAULT_DASHBOARD_ORIGINS,
    ...cfg.dashboardOrigins,
  ]);

  // CSP: default-src 'self' restricts content to the same origin. Scripts
  // are hashed by the Vite/React build, so 'self' works in production. Inline
  // styles from React hydration need 'unsafe-inline'. HSTS stays off because
  // this is a single-user local proxy served over HTTP (see README).
  //
  // `upgrade-insecure-requests` is emitted by Helmet by default; v0.6.6's
  // CSP hardening (#498) inherited it and broke HTTP LAN installs because the
  // browser rewrites /assets/* to https:// on an origin that has no TLS,
  // producing ERR_SSL_PROTOCOL_ERROR and a blank dashboard (#682).
  // The directive is dropped from the static Helmet config and re-added per
  // request below, gated by protocol + the CSP_UPGRADE_INSECURE_REQUESTS env.
  //
  // Cross-Origin-Opener-Policy and Origin-Agent-Cluster are handled the same
  // way, for the same reason: both only apply to secure contexts, so on a
  // plain-HTTP LAN origin the browser discards them and logs a console error
  // instead (#734). They are re-added per request whenever the origin is one
  // the browser trusts — HTTPS, or loopback, which covers desktop/localhost.
  app.use(helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        // index.html carries one inline <script>: the theme/direction bootstrap
        // that has to run before first paint, or every dark-mode user gets a
        // white flash. 'self' alone blocks it on every install, HTTPS included,
        // so it is allowed by hash — nothing else inline is. INLINE_BOOTSTRAP_SHA
        // is asserted against the real index.html in csp-inline-bootstrap.test.ts,
        // so editing that script fails the suite instead of silently breaking it.
        scriptSrc: ["'self'", INLINE_BOOTSTRAP_SHA],
        styleSrc: ["'self'", "'unsafe-inline'"],
        imgSrc: ["'self'", "data:"],
        connectSrc: ["'self'"],
        fontSrc: ["'self'"],
        formAction: ["'self'"],
        baseUri: ["'self'"],
        upgradeInsecureRequests: null,
      },
    },
    hsts: false,
    crossOriginOpenerPolicy: false,
    originAgentCluster: false,
  }));
  // Per-request re-issue of the headers that depend on how the page was
  // reached. Only HTTPS origins should tell the browser to upgrade http→https,
  // since plain-HTTP LAN setups have no TLS to upgrade to; the env flag
  // overrides that either way. COOP and Origin-Agent-Cluster go back on for any
  // origin the browser considers trustworthy (HTTPS or loopback), which is
  // every origin that would have honoured them in the first place.
  // Helmet ran above and synchronously set its headers on res; this runs next,
  // still before any route handler writes the body, so setHeader here lands
  // before the response is flushed.
  app.use((req, res, next) => {
    const shouldEmit =
      cfg.cspUpgradeInsecureRequests === true ||
      (cfg.cspUpgradeInsecureRequests === undefined && isHttpsRequest(req));

    if (shouldEmit) {
      const csp = res.getHeader('content-security-policy');
      if (typeof csp === 'string' && !csp.includes('upgrade-insecure-requests')) {
        res.setHeader('content-security-policy', `${csp}; upgrade-insecure-requests`);
      }
    }

    if (isTrustworthyOrigin(req)) {
      res.setHeader('Cross-Origin-Opener-Policy', 'same-origin');
      res.setHeader('Origin-Agent-Cluster', '?1');
    }

    next();
  });
  app.use(cors({
    origin(origin: string | undefined, callback: (err: Error | null, allow?: boolean) => void) {
      callback(null, !origin || allowedCorsOrigins.has(origin));
    },
  }));
  // Two-tier JSON body limits. The LLM wire surfaces carry vision payloads —
  // base64 images inline in the body (~33% inflation; google.ts forwards
  // images up to 8MB apiece) — so a single-screenshot Codex turn can clear
  // 10MB and used to 413 HERE, before auth/routing: no fallback attempt, no
  // analytics row, just an opaque 'request entity too large'. Those surfaces
  // get the larger REQUEST_BODY_LIMIT_MB ceiling (default 25MB); everything
  // else keeps the #200 limit — code agents (OpenCode, AionUI, Qwen Code)
  // ship very large system prompts + tool schemas + repo context, and 1mb cut
  // their sessions off mid-conversation. body-parser skips requests whose
  // body was already parsed, so the second parser only sees what the first
  // didn't own; an over-limit body throws from whichever parser matched.
  app.use(
    ['/v1', '/v1beta', '/mcp', '/api/chat', '/api/generate', '/api/embed', '/api/embeddings'],
    express.json({ limit: cfg.requestBodyLimitBytes }),
  );
  app.use(express.json({ limit: '10mb' }));

  // Caller identity (IP + User-Agent) for request analytics, carried in
  // AsyncLocalStorage so logRequest() can read it from any depth.
  app.use(clientContextMiddleware);

  // Ollama emulation owns only its exact fixed /api/* paths. Mount it before
  // the dashboard session gate because real Ollama clients do not use that
  // auth scheme. Its legacy /api/embeddings handler explicitly falls through
  // when it sees a valid dashboard session.
  // The same per-IP limiter as /v1 runs first: key-required mode is a
  // brute-forceable credential check without it. Dashboard traffic on the
  // shared /api/embeddings path shares the (generous, configurable) budget.
  app.use(
    ['/api/tags', '/api/version', '/api/show', '/api/chat', '/api/generate', '/api/embed', '/api/embeddings'],
    createProxyRateLimiter(cfg.proxyRateLimitRpm),
  );
  app.use(ollamaRouter);

  // Admin API — all routes share an IP-based rate limiter to throttle
  // brute-force attempts (auth, key export, etc). The limiter is mounted
  // broadly on /api; requireAuth gates each sub-path individually so that
  // unauthenticated endpoints under /api (like /api/ping) are not blocked.
  //
  // This MUST stay above the /api/auth mount below. Express runs middleware in
  // registration order, so while the limiter was registered after authRouter,
  // authRouter answered and ended /api/auth/login before the limiter was ever
  // entered — leaving the password endpoint this comment names as the reason
  // for the limiter as the one /api path it did not cover. It still sits below
  // the Ollama /api/* mount above, which carries its own proxy limiter.
  const adminRateLimiter = createAdminRateLimiter();
  app.use('/api', adminRateLimiter);

  // Dashboard auth (#35): /api/auth/{status,setup,login} bootstrap without a
  // session; everything else under /api/* requires a logged-in dashboard user.
  // The /v1 proxy keeps its own unified-API-key auth and is NOT gated here.
  app.use('/api/auth', authRouter);

  // Key export re-verifies the dashboard password, which makes it the one admin
  // endpoint a guesser can attack. The broad limiter above is sized for normal
  // dashboard traffic and far too loose for that, so this path gets its own
  // tight per-IP bucket on top of it.
  app.use('/api/keys/export', createAdminRateLimiter(EXPORT_RATE_LIMIT_RPM));

  app.use('/api/keys', requireAuth, keysRouter);
  // Per-client key management (#411). Dashboard-session gated like the rest of
  // /api — the profile keys it mints authenticate only the /v1 inference
  // surface and are never valid here.
  app.use('/api/client-profiles', requireAuth, clientProfilesRouter);
  // Saved Playground transcripts (the chat sidebar). Dashboard-session gated
  // like every other admin route; the unified /v1 key does not open it.
  app.use('/api/conversations', requireAuth, conversationsRouter);
  // Server logs for the dashboard viewer. Dashboard-session gated like the rest
  // of /api — these lines name providers, models and key ids, so the unified
  // /v1 key must not open them.
  app.use('/api/logs', requireAuth, logsRouter);
  app.use('/api/models', requireAuth, modelsRouter);
  app.use('/api/profiles', requireAuth, profilesRouter);
  app.use('/api/fallback', requireAuth, fallbackRouter);
  app.use('/api/embeddings', requireAuth, embeddingsRouter);
  app.use('/api/media', requireAuth, mediaRouter);
  app.use('/api/analytics', requireAuth, analyticsRouter);
  app.use('/api/health', requireAuth, healthRouter);
  app.use('/api/free-tier', requireAuth, freeTierRouter);
  app.use('/api/settings', requireAuth, settingsRouter);
  app.use('/api/premium', requireAuth, premiumRouter);
  // Database dumps and restores. Dashboard-session gated: the dump files carry
  // encrypted provider keys and every routing setting, so the unified /v1 key
  // must not open this surface.
  app.use('/api/backups', requireAuth, backupsRouter);
  app.use('/api/cache', requireAuth, cacheRouter);
  app.use('/api/compression', requireAuth, compressionRouter);
  app.use('/api/update', requireAuth, updateRouter);

  // Health check — no auth required.
  app.get('/api/ping', (_req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  // Static, unauthenticated API reference: GET /v1/docs (viewer) and
  // GET /v1/openapi.json (spec). Mounted before the rate limiter so the docs
  // are always reachable and don't draw down a caller's request budget. It only
  // owns those two paths; everything else falls through to the routers below.
  app.use('/v1', docsRouter);

  // Read-only per-upstream status for meta-gateways (GET /v1/providers, #433).
  // Unified-key auth is enforced inside the handler; mounted before the rate
  // limiter (like docsRouter) so status polling doesn't draw down a caller's
  // request budget.
  app.use('/v1', providersRouter);

  // Separately revocable URL tokens for clients that cannot set headers.
  app.use('/v1/t/:token', createProxyRateLimiter(cfg.proxyRateLimitRpm));
  app.use('/v1/t/:token', urlTokenRouter);

  // OpenAI-compatible proxy. Per-IP rate limiting (#35 item #6) runs first so
  // it throttles unauthenticated brute-force / flood attempts before any
  // routing work. Tune via PROXY_RATE_LIMIT_RPM; 0 disables it.
  app.use('/v1', createProxyRateLimiter(cfg.proxyRateLimitRpm));
  // Anthropic-compatible Messages API (`POST /v1/messages`, `/count_tokens`) for
  // Claude Code and anything else speaking the Anthropic SDK. Mounted BEFORE the
  // OpenAI router so it can content-negotiate `GET /v1/models` (Anthropic shape
  // when the caller sends `anthropic-version`, else it falls through). All other
  // paths it doesn't own fall through to the OpenAI router untouched.
  app.use('/v1', anthropicRouter);
  app.use('/v1', proxyRouter);
  // OpenAI Moderation API shim (POST /v1/moderations)
  app.use('/v1', moderationRouter);
  // OpenAI Responses API shim (Codex CLI requires wire_api="responses"; see #96)
  app.use('/v1', responsesRouter);

  // Native Gemini wire surface for Gemini CLI and Gemini-lineage agents.
  app.use('/v1beta', createProxyRateLimiter(cfg.proxyRateLimitRpm));
  app.use('/v1beta', geminiRouter);

  // MCP server (Model Context Protocol over stateless Streamable HTTP):
  // gateway introspection tools for MCP-speaking agents. Unified-key auth,
  // like /v1 — NOT behind the dashboard session gate. Same per-IP limiter as
  // /v1 (its own bucket): both surfaces guard the same unified key, so an
  // unauthenticated brute-force must not get a free throttle-less oracle here.
  app.use('/mcp', createProxyRateLimiter(cfg.proxyRateLimitRpm));
  app.use('/mcp', mcpRouter);

  // Liveness / readiness probes for orchestrators (GET /livez, /readyz, #433).
  // Unauthenticated so a load balancer can probe them; registered before the
  // static / SPA-fallback block below so these root paths resolve to JSON
  // instead of index.html.
  app.use(statusRouter);

  // Error handler (for API routes)
  app.use(errorHandler);

  // Serve client static files (after API error handler). CLIENT_DIST lets
  // embedders relocate the built dashboard (e.g. the desktop app ships it in
  // extraResources, where the __dirname-relative path can't reach).
  // Set serveStaticAssets: false in Config to skip static serving entirely
  // (e.g. in runtimes that serve assets through a different mechanism).
  if (cfg.serveStaticAssets) {
    const clientDist = cfg.clientDist
      ? path.resolve(cfg.clientDist)
      : path.resolve(__dirname, '../../client/dist');
    // Gzip the dashboard bundle (1+ MB uncompressed). Mounted HERE — after
    // every API/proxy router and the error handler — so it only wraps the
    // static-file / SPA-fallback responses below it. The /v1 and /api handlers
    // end their responses upstream and never fall through to this middleware,
    // so nothing (crucially the /v1/chat/completions SSE streams) gets buffered
    // or re-encoded by compression.
    app.use(compression());
    app.use(express.static(clientDist, {
      // Vite emits content-hashed build assets under assets/ (index-<hash>.js,
      // chunk-<hash>.js, *.css, fonts…). The URL changes whenever the bytes do,
      // so cache them for a year and mark them immutable. index.html and other
      // unhashed root entries must stay revalidated (no-cache) so a redeploy
      // propagates the new asset URLs immediately.
      setHeaders(res, filePath) {
        res.setHeader(
          'Cache-Control',
          isImmutableAsset(filePath)
            ? 'public, max-age=31536000, immutable'
            : 'no-cache',
        );
      },
    }));
    // SPA fallback — serve index.html for non-API routes
    app.use((req, res, next) => {
      if (req.path.startsWith('/api/') || req.path.startsWith('/v1/') || req.path.startsWith('/v1beta/')) {
        next();
        return;
      }
      // Same no-cache policy as the statically-served index.html: SPA deep
      // links must revalidate so a redeploy propagates new asset URLs.
      res.sendFile(path.join(clientDist, 'index.html'), {
        headers: { 'Cache-Control': 'no-cache' },
      });
    });
  }

  return app;
}

import type {
  ChatMessage,
  ChatCompletionResponse,
  ChatCompletionChunk,
  ChatToolDefinition,
  ChatToolChoice,
  Platform,
} from '@freellmapi/shared/types.js';
import type { QuotaObservationContext } from '../services/provider-quota.js';
import type { ExtendedSamplingOptions } from '../lib/sampling-params.js';
import { proxyFetch } from '../lib/proxy.js';
import { providerTimeoutMs, streamStallTimeoutMs } from '../lib/provider-timeout.js';
import { extractThinkTagsFromStream } from '../lib/think-tags.js';

/** A provider HTTP error carrying the upstream status and, when the provider
 *  stated one, the parsed back-off so the router can bench the key for at least
 *  that long. The delay may come from the Retry-After header or from the error
 *  body — see providerHttpError. */
export interface ProviderHttpError extends Error {
  status?: number;
  retryAfterMs?: number;
  /** Explicit daily-window violation from structured upstream quota details. */
  dailyQuotaExhausted?: boolean;
}

/** Upper bound on a provider-supplied back-off. A malformed or hostile
 *  `Retry-After` (e.g. 99999999999) would otherwise bench a key effectively
 *  forever, since the value feeds the cooldown expiry directly. A day is longer
 *  than any real free-tier reset window, so clamping cannot mask a genuine hint. */
const MAX_RETRY_AFTER_MS = 24 * 60 * 60 * 1000;

/** Parse an HTTP `Retry-After` header (delta-seconds or an HTTP-date) into a
 *  millisecond delay, clamped to MAX_RETRY_AFTER_MS. Returns undefined when
 *  absent or unparseable. */
export function parseRetryAfterMs(value: string | null | undefined): number | undefined {
  if (!value) return undefined;
  const trimmed = value.trim();
  if (/^\d+$/.test(trimmed)) return Math.min(Number(trimmed) * 1000, MAX_RETRY_AFTER_MS);
  const when = Date.parse(trimmed);
  if (!Number.isNaN(when)) {
    return Math.min(Math.max(0, when - Date.now()), MAX_RETRY_AFTER_MS);
  }
  return undefined;
}

/** A protobuf Duration, as google.rpc.RetryInfo spells its `retryDelay`:
 *  digits, an optional fraction, then a literal `s` ("17s", "1.5s", "0.25s"). */
const PROTOBUF_DURATION = /^(\d+(?:\.\d+)?)s$/;

/** "Please try again in 7.66s" / "retry after 30 seconds" / "try again in 2m".
 *  Anchored on an explicit retry phrase so an unrelated number in an error
 *  message can never be mistaken for a back-off. */
const PROSE_RETRY = /(?:try again|retry)\s+(?:in|after)\s+(\d+(?:\.\d+)?)\s*(ms|s|sec|secs|second|seconds|m|min|mins|minute|minutes|h|hour|hours)\b/i;

const UNIT_MS: Record<string, number> = {
  ms: 1,
  s: 1000, sec: 1000, secs: 1000, second: 1000, seconds: 1000,
  m: 60_000, min: 60_000, mins: 60_000, minute: 60_000, minutes: 60_000,
  h: 3_600_000, hour: 3_600_000, hours: 3_600_000,
};

function clampRetryMs(ms: number): number | undefined {
  if (!Number.isFinite(ms) || ms < 0) return undefined;
  return Math.min(ms, MAX_RETRY_AFTER_MS);
}

/** Depth-first search for the first `retryDelay`/`retry_after`-shaped field. The
 *  shape varies by provider and by endpoint within a provider, so walking is
 *  more durable than a list of exact paths — and cheaper to maintain than one
 *  parser per adapter. Depth-capped so a pathological body cannot spin. */
function findStatedDelayMs(node: unknown, depth = 0): number | undefined {
  if (depth > 6 || node === null || typeof node !== 'object') return undefined;

  if (Array.isArray(node)) {
    for (const item of node) {
      const found = findStatedDelayMs(item, depth + 1);
      if (found !== undefined) return found;
    }
    return undefined;
  }

  for (const [key, value] of Object.entries(node as Record<string, unknown>)) {
    const normalized = key.toLowerCase().replace(/[_-]/g, '');
    if (normalized === 'retrydelay' || normalized === 'retryafter' || normalized === 'retryafterseconds') {
      // google.rpc.RetryInfo states "17s"; other providers state bare seconds.
      if (typeof value === 'string') {
        const duration = PROTOBUF_DURATION.exec(value.trim());
        if (duration) return clampRetryMs(Number(duration[1]) * 1000);
        if (/^\d+(\.\d+)?$/.test(value.trim())) return clampRetryMs(Number(value) * 1000);
      }
      if (typeof value === 'number') return clampRetryMs(value * 1000);
    }
    const found = findStatedDelayMs(value, depth + 1);
    if (found !== undefined) return found;
  }
  return undefined;
}

/**
 * The back-off a provider stated inside its error BODY, in milliseconds.
 *
 * Not every provider uses the Retry-After header. Gemini answers a 429 with
 * `error.details[]` carrying a `google.rpc.RetryInfo` whose `retryDelay` is
 * "17s", and several OpenAI-compatible tiers only say it in prose. Those hints
 * were being thrown away: the body is flattened to a single message string
 * before it reaches the router, so a provider that told us exactly when to come
 * back got the same heuristic cooldown ladder as one that said nothing.
 */
export function parseStatedRetryMs(body: unknown): number | undefined {
  if (body == null) return undefined;

  if (typeof body !== 'string') {
    const structured = findStatedDelayMs(body);
    if (structured !== undefined) return structured;
  }

  // Prose last: a stated field is a promise, a sentence is an observation.
  const text = typeof body === 'string' ? body : safeStringify(body);
  const prose = text ? PROSE_RETRY.exec(text) : null;
  if (prose) {
    const unit = UNIT_MS[prose[2].toLowerCase()];
    if (unit) return clampRetryMs(Number(prose[1]) * unit);
  }
  return undefined;
}

function safeStringify(value: unknown): string {
  try {
    return JSON.stringify(value) ?? '';
  } catch {
    return ''; // Circular or otherwise unserialisable — no prose to read.
  }
}

/** Build an error for a non-OK upstream response, capturing the status and any
 *  stated back-off. Used by every provider adapter so the proxy can honor a
 *  provider's explicit hint when it sets the cooldown.
 *
 *  `body` is the already-parsed error payload the caller used to build
 *  `message`. Only a delay is read out of it and only a number is kept — the
 *  body itself is never retained, so nothing extra reaches a log or the
 *  attempt trace. The Retry-After header still wins when both are present: it
 *  is the standard channel, and preferring it keeps existing behavior exactly
 *  as it was. */
export function providerHttpError(res: Response, message: string, body?: unknown): ProviderHttpError {
  const err = new Error(message) as ProviderHttpError;
  err.status = res.status;
  const retryAfterMs = parseRetryAfterMs(res.headers?.get('retry-after')) ?? parseStatedRetryMs(body);
  if (retryAfterMs !== undefined) err.retryAfterMs = retryAfterMs;
  return err;
}

// Extended sampling knobs (top_k, seed, penalties, logit_bias, logprobs,
// response_format…) ride along via ExtendedSamplingOptions; adapters forward
// them per the platform policy in lib/sampling-params.ts.
export interface CompletionOptions extends ExtendedSamplingOptions {
  model?: string;
  temperature?: number;
  max_tokens?: number;
  top_p?: number;
  stop?: string | string[];
  tools?: ChatToolDefinition[];
  tool_choice?: ChatToolChoice;
  parallel_tool_calls?: boolean;
  stream_options?: {
    include_usage?: boolean;
  };
  /** Remaining context budget (context_window − estimated_input_tokens) for
   *  this route. resolveMaxTokens clamps max_tokens to fit. */
  contextBudget?: number;
  /** Per-call HTTP timeout override. Not part of the OpenAI wire format (it is
   * stripped before the request body is built); used by the probe script so
   * NVIDIA's 15-60s serverless cold starts don't read as failures. */
  timeoutMs?: number;
  /** Abort signal for the gateway's OWN client (request socket closed). The
   * proxy surfaces thread it here so a disconnect cancels the upstream fetch
   * AND any in-progress body/stream read — tokens stop burning and the
   * in-flight lease frees immediately instead of when the read happens to
   * finish. Composed with the per-attempt timeout in fetchWithTimeout; never
   * serialized into the request body. */
  signal?: AbortSignal;
}

/** Per-call abort/timeout wiring for fetchWithTimeout. */
export interface ProviderFetchOptions {
  /** Client-disconnect signal, composed with the per-attempt timeout via
   * AbortSignal.any. Unlike the timeout it is never disarmed at headers, so it
   * also aborts body reads and stream iteration through undici. */
  signal?: AbortSignal;
  /** What the per-attempt timeout bounds:
   *  - 'headers' (default, historical): the abort timer dies the moment
   *    response HEADERS arrive — right for streams, whose body legitimately
   *    outlives any fixed deadline (readSseStream's stall watchdog owns
   *    mid-stream hangs, the client signal owns "nobody is listening").
   *  - 'request': the deadline stays armed across the body read too, so a 200
   *    whose body never finishes aborts at timeoutMs instead of hanging
   *    res.json() forever. Use for non-streaming calls, which read the whole
   *    body as one unit. */
  timeoutBounds?: 'headers' | 'request';
}

/** Per-stream timeout wiring for readSseStream (#584). */
export interface SseStreamOptions {
  /** The chat timeout the adapter gave fetchWithTimeout for this request
   * (options.timeoutMs override included). Becomes the first-byte grace
   * budget, floored at the stall budget — see firstByteBudgetMs. Defaults to
   * fetchWithTimeout's own default, providerTimeoutMs(platform, 15000). */
  firstByteTimeoutMs?: number;
  /** Mid-stream inactivity budget; defaults to streamStallTimeoutMs(platform)
   * (per-platform env > global env > 90s). 0 disables the watchdog. */
  stallTimeoutMs?: number;
}

export interface KeyValidationFailure {
  valid: false;
  /** Provider-supplied reason suitable for health logs and the local keys UI. */
  error: string;
}

export type KeyValidationResult = boolean | KeyValidationFailure;

export abstract class BaseProvider {
  abstract readonly platform: Platform;
  abstract readonly name: string;
  /** Providers whose free tier needs no API key (e.g. Kilo's anonymous gateway).
   * When true, the gateway stores a sentinel key row so routing still considers
   * the platform "configured", and the provider omits the Authorization header
   * on outgoing requests. Defaults to false; set by subclasses. */
  keyless = false;

  abstract chatCompletion(
    apiKey: string,
    messages: ChatMessage[],
    modelId: string,
    options?: CompletionOptions,
    quotaContext?: QuotaObservationContext,
  ): Promise<ChatCompletionResponse>;

  abstract streamChatCompletion(
    apiKey: string,
    messages: ChatMessage[],
    modelId: string,
    options?: CompletionOptions,
    quotaContext?: QuotaObservationContext,
  ): AsyncGenerator<ChatCompletionChunk>;

  abstract validateKey(apiKey: string, quotaContext?: QuotaObservationContext): Promise<KeyValidationResult>;

  /**
   * Optional quota/balance probe (#1403). Providers whose API exposes a
   * key-info/quota endpoint override this to fetch the provider-reported
   * limit/remaining and persist them as a `source: 'quota_api'` observation,
   * so the dashboard shows a real balance instead of a text-label guess.
   * Must never throw into the caller: the default implementation does no
   * network at all and returns false; implementations catch transport errors
   * and return false so a quota probe can never change a health verdict.
   * Returns true when an observation was recorded.
   */
  async fetchQuota(_apiKey: string, _quotaContext?: QuotaObservationContext): Promise<boolean> {
    return false;
  }

  /** Whether this provider actually has a quota endpoint to probe (#1403).
   * fetchQuota alone can't answer it: OpenAICompatProvider overrides the
   * method for every instance, spec or not. Routes that owe the operator a
   * "this platform has no quota endpoint" answer must use this instead. */
  get hasQuotaProbe(): boolean {
    return false;
  }

  /** Whether the health checker may probe this provider's keys at all (#1459).
   * A provider that forbids automated key checks (LLMTR answers any probe with
   * 403 "automated API key validation tools are not supported", and its
   * security system suspends accounts that keep sending them) returns false:
   * the health pass and the cooldown probe then never call validateKey for its
   * keys, and a key is promoted to healthy by the first request it serves
   * (markKeyHealthyFromRequest) instead of by a probe. */
  get supportsKeyValidation(): boolean {
    return true;
  }

  /**
   * Turn a conventional 401/403 validation response into a diagnostic result.
   * Providers still return a simple boolean when no useful error body exists,
   * but preserving the upstream message here lets the health service persist
   * and display the reason instead of reducing every failure to "invalid".
   */
  protected async validationResult(res: Response): Promise<KeyValidationResult> {
    if (res.status !== 401 && res.status !== 403) return true;
    // A Cloudflare bot challenge ("Just a moment...") is a 403 about the
    // caller's IP and User-Agent, not about the key. Surface it as
    // inconclusive so health never auto-disables a good key behind it (#1298).
    if (res.headers?.get('cf-mitigated') === 'challenge') {
      throw providerHttpError(res, `${this.name} key validation blocked by a Cloudflare challenge (HTTP ${res.status}); the key was not checked`);
    }

    let body: any = null;
    try {
      if (typeof (res as any).json === 'function') body = await res.json();
    } catch {
      // A status and provider name are still more useful than no reason.
    }

    const detail = [
      body?.error?.message,
      body?.errors?.[0]?.message,
      body?.message,
      body?.detail,
      body?.title,
      res.statusText,
    ].find((value) => typeof value === 'string' && value.trim().length > 0);

    return {
      valid: false,
      error: `${this.name} key validation failed (HTTP ${res.status})${detail ? `: ${detail}` : ''}`,
    };
  }

  protected async fetchWithTimeout(
    url: string,
    init: RequestInit,
    // Adapters that don't pass a timeout inherit the platform's env override
    // (PROVIDER_TIMEOUT_<PLATFORM>, issue #547) over the historical 15s.
    timeoutMs = providerTimeoutMs(this.platform, 15000),
    fetchOpts?: ProviderFetchOptions,
  ): Promise<Response> {
    const signals: AbortSignal[] = [];
    if (fetchOpts?.signal) signals.push(fetchOpts.signal);

    // timeoutMs <= 0 means "no timeout" (PROVIDER_TIMEOUT_<PLATFORM>=0).
    // setTimeout(abort, 0) would abort every request on the next macrotask.
    let headerTimer: ReturnType<typeof setTimeout> | undefined;
    if (timeoutMs > 0) {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), timeoutMs);
      signals.push(controller.signal);
      if (fetchOpts?.timeoutBounds === 'request') {
        // Whole-request deadline: stays armed across the body read, so a 200
        // whose body never finishes aborts res.json() at timeoutMs instead of
        // hanging forever. Never cleared — firing after the response is fully
        // consumed is a no-op — and unref'd so a spent request's leftover
        // deadline can't hold the process open.
        timer.unref?.();
      } else {
        // Historical header-only deadline: disarmed the moment response
        // HEADERS arrive (see finally). Streams need this — an SSE body
        // legitimately outlives any fixed deadline, and mid-stream hangs are
        // owned by the stall watchdog (readSseStream) + the client signal.
        headerTimer = timer;
      }
    }

    // Compose the per-attempt timeout with the client-disconnect signal.
    // Unlike the timeout, the client signal is never disarmed: undici ties it
    // to the whole request, so a disconnect also aborts body reads and stream
    // iteration, rejecting them with the marked reason from newClientAbortError.
    const signal = signals.length === 0
      ? init.signal ?? undefined
      : signals.length === 1 ? signals[0] : AbortSignal.any(signals);

    try {
      // requestType='chat' + timeoutMs makes the AbortError message read
      // `<platform>, chat, 15s` for triage from the requests.error column.
      return await proxyFetch(url, signal ? { ...init, signal } : init, this.platform, 'chat', timeoutMs);
    } finally {
      if (headerTimer !== undefined) clearTimeout(headerTimer);
    }
  }

  protected makeId(): string {
    return `chatcmpl-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  }

  /**
   * One reader.read() bounded by the mid-stream inactivity watchdog (#553).
   * Shared by readSseStream and adapters that parse their own wire format
   * (google.ts) so every stream gets the same stall semantics:
   * PROVIDER_STREAM_STALL_TIMEOUT_MS (per-platform override
   * PROVIDER_STREAM_STALL_TIMEOUT_<PLATFORM>, #584), default 90s, 0 disables.
   * Client-abort rejections pass through untouched — undici errors the body
   * with the request signal's reason, so a disconnect surfaces here as the
   * marked error from newClientAbortError, not as a stall. `timeoutMessage`
   * lets the first-byte read report its distinct wording (#584).
   */
  protected async readWithStallTimeout<T>(
    read: () => Promise<T>,
    inactivityTimeoutMs: number,
    timeoutMessage?: string,
  ): Promise<T> {
    if (inactivityTimeoutMs <= 0) return read();
    let timer: ReturnType<typeof setTimeout> | undefined;
    return Promise.race([
      read(),
      new Promise<never>((_, reject) => {
        timer = setTimeout(
          () => reject(new Error(timeoutMessage ?? `${this.name} stream stalled: no data for ${inactivityTimeoutMs}ms (timeout)`)),
          inactivityTimeoutMs,
        );
      }),
    ]).finally(() => clearTimeout(timer));
  }

  /**
   * Budget for the FIRST read of a streaming body (issue #584): the platform's
   * chat timeout is already "how slow may the first token be" — tuned per
   * platform at registration and env-overridable via PROVIDER_TIMEOUT_<PLATFORM>
   * — but on streams it is disarmed the moment response HEADERS arrive, and
   * providers like NVIDIA NIM send SSE headers instantly then prefill for
   * minutes. Floored at the stall budget so a platform with a short chat
   * timeout never gets a STRICTER first read than the pre-#584 watchdog gave
   * it. 0 on either side (env-disabled chat timeout, or disabled watchdog)
   * means the first read is unbounded — the client signal still owns
   * "nobody is listening".
   */
  protected firstByteBudgetMs(chatTimeoutMs: number, stallTimeoutMs: number): number {
    if (chatTimeoutMs <= 0 || stallTimeoutMs <= 0) return 0;
    return Math.max(chatTimeoutMs, stallTimeoutMs);
  }

  /** Distinct wording for a first-byte timeout (vs a mid-stream stall) so the
   * attempt-trace error_summary tells slow prefill apart from a dead stream. */
  protected firstByteTimeoutMessage(budgetMs: number): string {
    return `${this.name} stream: no first byte within ${budgetMs}ms (first-byte timeout)`;
  }

  /**
   * Shared SSE reader for OpenAI-wire streaming endpoints (#231 audit).
   *
   * Hardened against the upstream failure modes observed live:
   *  - Inactivity timeout: fetchWithTimeout's abort timer dies the moment
   *    response HEADERS arrive, so a provider that stalls mid-body used to
   *    hang the client forever. Each read now has its own deadline. The FIRST
   *    read gets a grace budget derived from the platform's chat timeout
   *    (#584) — SSE headers can arrive instantly while the model prefills a
   *    long prompt for minutes, which is slow, not stalled.
   *  - Abrupt EOF: a stream that ends without `[DONE]` AND without any
   *    `finish_reason` is a truncated generation, not a completion. It used
   *    to end the generator silently (truncation logged as success); it now
   *    throws a retryable error so the proxy can fail over or report it.
   *    Providers that skip `[DONE]` but do send a terminal finish_reason
   *    (several compat shims) still complete normally.
   *
   * Malformed data lines are skipped, matching previous behavior.
   *
   * The frames additionally pass through the inline `<think>` extractor
   * (lib/think-tags.ts): DeepSeek-style models that serialize their reasoning
   * trace INTO delta.content as a leading `<think>…</think>` block get it
   * moved to delta.reasoning_content, so downstream surfaces never render
   * thinking as answer text. Streams without the tag are forwarded verbatim.
   */
  protected async *readSseStream(
    res: Response,
    opts?: SseStreamOptions,
  ): AsyncGenerator<ChatCompletionChunk> {
    yield* extractThinkTagsFromStream(this.readSseFrames(res, opts));
  }

  private async *readSseFrames(
    res: Response,
    opts?: SseStreamOptions,
  ): AsyncGenerator<ChatCompletionChunk> {
    const reader = res.body?.getReader();
    if (!reader) throw new Error('No response body');

    // The 90s default was hardcoded and silently truncated slow streams — the
    // gateway ended them with an error frame plus a clean [DONE] that OpenAI
    // SDK clients swallow, so responses "just stopped" (issue #553). Operators
    // proxying slow free tiers can raise it (or 0 to disable) via
    // PROVIDER_STREAM_STALL_TIMEOUT_MS, or per platform via
    // PROVIDER_STREAM_STALL_TIMEOUT_<PLATFORM> (#584).
    const inactivityTimeoutMs = opts?.stallTimeoutMs ?? streamStallTimeoutMs(this.platform);
    // First-byte grace (#584): adapters pass the same chat timeout they gave
    // fetchWithTimeout; the fallback mirrors fetchWithTimeout's own default so
    // adapters that never tuned either stay on max(15s-or-env, stall) — i.e.
    // exactly the stall budget they had before.
    const chatTimeoutMs = opts?.firstByteTimeoutMs ?? providerTimeoutMs(this.platform, 15000);
    const firstByteMs = this.firstByteBudgetMs(chatTimeoutMs, inactivityTimeoutMs);

    const decoder = new TextDecoder();
    let buffer = '';
    let sawFinishReason = false;
    let awaitingFirstByte = true;

    try {
      while (true) {
        const { done, value } = awaitingFirstByte
          ? await this.readWithStallTimeout(() => reader.read(), firstByteMs, this.firstByteTimeoutMessage(firstByteMs))
          : await this.readWithStallTimeout(() => reader.read(), inactivityTimeoutMs);
        awaitingFirstByte = false;
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop() ?? '';

        for (const line of lines) {
          const trimmed = line.trim();
          if (!trimmed || !trimmed.startsWith('data:')) continue;
          const data = trimmed.slice(5).replace(/^ /, '');
          if (data === '[DONE]') return;
          try {
            const chunk = JSON.parse(data) as ChatCompletionChunk;
            if (chunk.choices?.some(c => c.finish_reason != null)) sawFinishReason = true;
            yield chunk;
          } catch {
            // Skip malformed chunks
          }
        }
      }
    } finally {
      reader.cancel().catch(() => { /* upstream already gone */ });
    }

    if (!sawFinishReason) {
      throw new Error(`${this.name} stream ended unexpectedly (no [DONE], no finish_reason) — connection reset or truncated upstream`);
    }
  }
}

import crypto from 'crypto';
import fs from 'fs';
import path from 'path';
import { restrictToOwner } from './file-permissions.js';
import type { Db } from '../db/types.js';

const ALGORITHM = 'aes-256-gcm';

let cachedKey: Buffer | null = null;

/**
 * AES-256-GCM uses a 32-byte key, hex-encoded as 64 chars.
 * A typo'd ENCRYPTION_KEY (e.g. "abc") would historically fall through
 * the placeholder check, get truncated to 1.5 bytes, and only fail at
 * the first encrypt() call with a cryptic node:crypto error. Validate
 * the length up front and fail fast with an actionable message.
 */
const KEY_BYTES = 32;
const KEY_HEX_LEN = KEY_BYTES * 2;
const PLACEHOLDER_KEY = 'your-64-char-hex-key-here';

// The dev-fallback key lives in a file next to the DB, NOT in the DB itself.
// Storing it beside the ciphertext it protects (the old `settings` row) meant
// encryption-at-rest protected nothing for a default install: whoever copied
// the DB also copied the key. The file sits in the same directory but is a
// separate artifact, and is chmod 0600 so it isn't world-readable.
const KEY_FILE_NAME = '.encryption-key';

function parseHexKey(value: string, source: 'env' | 'db' | 'file'): Buffer {
  if (value.length !== KEY_HEX_LEN || !/^[0-9a-fA-F]+$/.test(value)) {
    throw new Error(
      `Invalid ENCRYPTION_KEY (${source}): expected ${KEY_HEX_LEN} hex chars (32 bytes), got ${value.length} chars. ` +
      `Generate one with: node -e "console.log(require('crypto').randomBytes(32).toString('hex'))"`,
    );
  }
  return Buffer.from(value, 'hex');
}

// Outside production we auto-generate and persist a key so a fresh clone
// (`npm run dev`) boots without manual setup — the placeholder ENCRYPTION_KEY
// in .env.example would otherwise crash the server on boot, which surfaces in
// the client as "Can't reach the server". Production still requires an explicit
// env key: a generated key lives only on the local disk and silently losing it
// would make every stored API key undecryptable.
function isDevFallbackAllowed(): boolean {
  return process.env.NODE_ENV !== 'production';
}

function missingKeyError(): Error {
  return new Error(
    'ENCRYPTION_KEY is required in production for API key encryption. ' +
    `Set a ${KEY_HEX_LEN}-char hex key (generate one with: ` +
    `node -e "console.log(require('crypto').randomBytes(32).toString('hex'))"). ` +
    'Outside production a local key file is auto-generated next to the database.',
  );
}

// The directory that holds the DB is the only place we can keep the key file
// next to (but not inside) the database. In-memory and anonymous databases have
// no such directory (db.memory is true, db.name is ":memory:" or ""), and Db
// backings without file metadata (memory undefined) have none either, so those
// callers fall back to the legacy settings-table behavior.
function keyFilePathFor(db: Db): string | null {
  if (db.memory !== false) return null;
  const dbPath = db.name;
  if (!dbPath || dbPath === ':memory:') return null;
  return path.join(path.dirname(dbPath), KEY_FILE_NAME);
}

// Write the hex key with a temp-file-and-rename so a crash never leaves a
// half-written key, and restrict it to the owner so it isn't readable by other
// local users. The temp file is restricted BEFORE the rename so the key is
// never briefly world-readable under its final name; a rename carries the DACL
// with it, and the second call is idempotent belt-and-braces.
function writeKeyFileAtomic(keyFile: string, hex: string): void {
  const dir = path.dirname(keyFile);
  const tmp = path.join(dir, `${KEY_FILE_NAME}.tmp-${crypto.randomBytes(6).toString('hex')}`);
  fs.writeFileSync(tmp, hex, { mode: 0o600 });
  restrictToOwner(tmp);
  fs.renameSync(tmp, keyFile);
  if (!restrictToOwner(keyFile)) {
    console.warn(`[crypto] could not restrict permissions on ${KEY_FILE_NAME} — it may be readable by other local accounts`);
  }
}

/**
 * Initialize encryption key from env or an explicit local-dev fallback.
 * Must be called after DB is initialized.
 *
 * Precedence (dev fallback): ENCRYPTION_KEY env > existing key file next to the
 * DB > legacy `settings` table row (migrated to the file, then deleted) >
 * freshly generated key written to the file.
 */
export function initEncryptionKey(db: Db): void {
  // 1. Explicit env key always wins.
  const envKey = process.env.ENCRYPTION_KEY;
  if (envKey && envKey !== PLACEHOLDER_KEY) {
    cachedKey = parseHexKey(envKey, 'env');
    return;
  }

  if (!isDevFallbackAllowed()) {
    throw missingKeyError();
  }

  const keyFile = keyFilePathFor(db);

  // In-memory / anonymous DBs have no directory to hold a key file, so keep the
  // legacy settings-table behavior for them (ephemeral runs, most tests).
  if (!keyFile) {
    const row = db.prepare("SELECT value FROM settings WHERE key = 'encryption_key'").get() as { value: string } | undefined;
    if (row) {
      cachedKey = parseHexKey(row.value, 'db');
      console.warn('[crypto] No ENCRYPTION_KEY set — using an auto-generated in-memory key (dev only).');
      return;
    }
    cachedKey = crypto.randomBytes(KEY_BYTES);
    db.prepare("INSERT INTO settings (key, value) VALUES ('encryption_key', ?)").run(cachedKey.toString('hex'));
    console.warn('[crypto] No ENCRYPTION_KEY set — generated an in-memory dev key. Set ENCRYPTION_KEY for production.');
    return;
  }

  // 2. An existing key file next to the DB.
  if (fs.existsSync(keyFile)) {
    const value = fs.readFileSync(keyFile, 'utf8').trim();
    cachedKey = parseHexKey(value, 'file');
    console.warn(`[crypto] No ENCRYPTION_KEY set — using the auto-generated key at ${keyFile} (dev only). Set ENCRYPTION_KEY for production.`);
    return;
  }

  // 3. A legacy key still sitting in the settings table (older dev installs).
  //    Migrate it to the key file so the DB stops storing the key that protects
  //    it, confirm a decrypt round-trip with the migrated key, then drop the row.
  const legacy = db.prepare("SELECT value FROM settings WHERE key = 'encryption_key'").get() as { value: string } | undefined;
  if (legacy) {
    const migrated = parseHexKey(legacy.value, 'db');
    writeKeyFileAtomic(keyFile, migrated.toString('hex'));
    cachedKey = migrated;
    const probe = encrypt('roundtrip');
    if (decrypt(probe.encrypted, probe.iv, probe.authTag) !== 'roundtrip') {
      cachedKey = null;
      throw new Error('[crypto] Failed to migrate the DB-stored key to a key file: round-trip check failed.');
    }
    db.prepare("DELETE FROM settings WHERE key = 'encryption_key'").run();
    console.warn(`[crypto] Migrated the legacy DB-stored key to ${keyFile} and removed it from the database (dev only). Set ENCRYPTION_KEY for production.`);
    return;
  }

  // 4. Generate a fresh key and persist it to the file.
  cachedKey = crypto.randomBytes(KEY_BYTES);
  writeKeyFileAtomic(keyFile, cachedKey.toString('hex'));
  console.warn(`[crypto] No ENCRYPTION_KEY set — generated a local dev key at ${keyFile}. Set ENCRYPTION_KEY for production.`);
}

function getEncryptionKey(): Buffer {
  if (!cachedKey) {
    throw new Error('Encryption key not initialized. Call initEncryptionKey() first.');
  }
  return cachedKey;
}

/**
 * A short, non-reversible identifier for the key currently in use.
 *
 * Database dumps record it in their header so a restore can tell, before it
 * touches a row, whether the api_keys ciphertext in the file was written under
 * this key. sha256 truncated to 64 bits: enough to catch a different key,
 * nowhere near enough to help recover the key itself, and safe to show in an
 * error message or write to a file an operator emails around.
 *
 * Returns null before initEncryptionKey() has run.
 */
export function encryptionKeyFingerprint(): string | null {
  if (!cachedKey) return null;
  return `sha256:${crypto.createHash('sha256').update(cachedKey).digest('hex').slice(0, 16)}`;
}

export function isEncryptionKeyInitialized(): boolean {
  return cachedKey !== null;
}

export function encrypt(text: string): { encrypted: string; iv: string; authTag: string } {
  const key = getEncryptionKey();
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv(ALGORITHM, key, iv);

  let encrypted = cipher.update(text, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const authTag = cipher.getAuthTag().toString('hex');

  return {
    encrypted,
    iv: iv.toString('hex'),
    authTag,
  };
}

// AUTH_TAG_BYTES pins the GCM tag length to 16 bytes. Without this option Node
// will accept any tag of length 4–16 bytes (RFC 5116 §3.2), which lets anyone
// who can rewrite a row in `api_keys` swap in a 4-byte tag and start brute-
// forcing forgeries at 2^32 attempts. Pinning closes that truncation path.
const AUTH_TAG_BYTES = 16;

export function decrypt(encrypted: string, iv: string, authTag: string): string {
  const key = getEncryptionKey();
  const decipher = crypto.createDecipheriv(ALGORITHM, key, Buffer.from(iv, 'hex'), { authTagLength: AUTH_TAG_BYTES });
  decipher.setAuthTag(Buffer.from(authTag, 'hex'));

  let decrypted = decipher.update(encrypted, 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  return decrypted;
}

// A masked key is display-only — it feeds the `maskedKey` field every key,
// media, embedding and client-profile route hands to the dashboard — so it must
// never be enough to reconstruct the secret. The old short-key branch was
// `'****' + key.slice(-4)`, and slice(-4) keeps the last four characters no
// matter how short the input is: a 4-character key was echoed back IN FULL, and
// a 5-character key gave away 4 of its 5 characters. Short keys are not
// hypothetical — proxy credentials, self-hosted Ollama tokens and local dev
// keys all land here.
//
// So reveal nothing at all below 5 characters, and at most the last TWO up to
// 8: enough tail to tell two rows apart in the UI, not enough to be a
// meaningful share of the secret. Long keys keep the familiar prefix+suffix
// form, where 8 revealed characters out of 20+ is a fixed, small fraction.
export function maskKey(key: string): string {
  if (key.length < 5) return '****';
  if (key.length <= 8) return '****' + key.slice(-2);
  return key.slice(0, 4) + '...' + key.slice(-4);
}

